const test = require('node:test');
const assert = require('node:assert/strict');
const { jobLabel } = require('../job-label.cjs');
test('pads short job serials on the left', () => {
  for (const [serial, expected] of [[0,'0000'],[7,'0007'],[27,'0027'],[350,'0350'],[1000,'1000'],[12345,'12345'],[9007199254740991,'9007199254740991']]) {
    assert.equal(jobLabel(serial), expected);
  }
});

